from __future__ import annotations

import json
from pathlib import Path

from .workflow_helper import run_cli, run_shell

GCODE = (
    "; HEADER_BLOCK_START\n; generated by Snapmaker Orca 2.4.0\n; HEADER_BLOCK_END\n\n"
    "G90\nM83\nT0\n;TYPE:Outer wall\n"
    + "".join(f"G1 Z{z}\nG1 X10 Y10\nG1 X40 Y10 E1\nG1 X40 Y25 E1\nG1 X10 Y25 E1\nG1 X10 Y10 E1\n" for z in (0.2, 0.4))
    + "; CONFIG_BLOCK_START\n; filament_colour = #C12E1F\n; thumbnails = 48x48/PNG, 300x300/PNG\n"
    "; thumbnails_format = PNG\n; CONFIG_BLOCK_END\n"
)


def test_headless_slice_gets_the_thumbnails_its_printer_profile_asks_for(tmp_path: Path) -> None:
    """A user sliced a plate with the Orca CLI, sees a blank preview on the printer screen,
    adds the thumbnails and confirms the G-code now carries every size the profile names."""
    plate = tmp_path / "plate.gcode"
    plate.write_text(GCODE, encoding="ascii")

    before = run_cli(tmp_path, "gcode-thumbnails", "check", str(plate))
    assert before.returncode == 1
    assert "FAIL" in before.stdout and "missing 48x48/PNG, 300x300/PNG" in before.stdout

    added = run_cli(tmp_path, "gcode-thumbnails", "add", str(plate), "--json")
    assert added.returncode == 0, added.stderr
    payload = json.loads(added.stdout)
    assert payload[0]["ok"] is True
    assert payload[0]["added"] == ["48x48/PNG", "300x300/PNG"]

    text = plate.read_text(encoding="ascii")
    assert text.index("; thumbnail begin 48x48") < text.index("; thumbnail begin 300x300") < text.index("\nG90")
    assert text.endswith(GCODE[GCODE.index("G90"):])

    after = run_cli(tmp_path, "gcode-thumbnails", "check", str(plate))
    assert after.returncode == 0
    assert "PASS" in after.stdout


def test_preflight_shell_chain_lists_files_without_a_preview(tmp_path: Path) -> None:
    """Before an upload a user checks a folder of G-code in one pipe and keeps the report."""
    (tmp_path / "a.gcode").write_text(GCODE, encoding="ascii")
    (tmp_path / "b.gcode").write_text(GCODE, encoding="ascii")
    result = run_shell(
        '"$THREED" gcode-thumbnails add b.gcode > add.log 2> add.err && '
        '"$THREED" gcode-thumbnails check a.gcode b.gcode | grep FAIL > report.txt; cat report.txt',
        tmp_path,
    )
    report = (tmp_path / "report.txt").read_text(encoding="utf-8")
    assert "a.gcode" in report and "b.gcode" not in report
    assert "PASS" in (tmp_path / "add.log").read_text(encoding="utf-8")
    assert result.stdout == report


def test_unknown_subcommand_names_the_valid_ones(tmp_path: Path) -> None:
    """A user mistypes the subcommand and is told which ones exist."""
    result = run_cli(tmp_path, "gcode-thumbnails", "inject", "x.gcode")
    assert result.returncode == 2
    assert "check" in result.stderr and "add" in result.stderr
